window.BlackoutObserver = (function () {
  const MIC_LABELS = {
    listening: "在听",
    paused: "暂停",
    user_speaking: "你在说",
    ai_speaking: "AI 在说",
    offline: "未连接"
  };
  const ACTION_LABELS = {
    listen: "听着，没打断",
    follow_up: "追问没说完的点",
    pull_back: "拉回主线",
    continue: "推进",
    answer: "回答",
    summarize: "确认结束"
  };
  let sessionId = "";
  let timer = 0;
  let subtitleTimer = 0;
  let lastParkingJson = "";
  let parkingSeen = false;
  let lastSubtitleText = "";
  function el(id) { return document.getElementById(id); }
  function sessionParam() {
    try { return new URLSearchParams(window.location.search).get("session") || ""; } catch (e) { return ""; }
  }
  function showMessage(text) {
    const node = el("obsMessage");
    node.textContent = String(text || "");
    node.hidden = !text;
  }
  function armSubtitleFade(text) {
    if (text === lastSubtitleText) { return; }
    lastSubtitleText = text;
    const box = document.querySelector(".subtitles");
    if (box) { box.classList.remove("faded"); }
    window.clearTimeout(subtitleTimer);
    subtitleTimer = window.setTimeout(function () {
      if (box) { box.classList.add("faded"); }
    }, 8000);
  }
  function renderParking(parking) {
    const list = el("obsParking");
    const json = JSON.stringify(parking || []);
    const isNew = parkingSeen && json !== lastParkingJson;
    list.replaceChildren();
    (parking || []).forEach(function (item, index) {
      const li = document.createElement("li");
      li.textContent = String(item || "");
      if (isNew && index === (parking || []).length - 1) { li.className = "new"; }
      list.appendChild(li);
    });
    parkingSeen = true;
    lastParkingJson = json;
  }
  function renderMap(record) {
    if (!window.BlackoutMap || !record || !record.map) { return; }
    const svg = el("obsMap");
    if (!svg) { return; }
    svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
    window.BlackoutMap.render(svg, record.map, { theme: "night", animate: true });
    svg.classList.add("map");
    svg.classList.add("map-night");
    svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
  }
  function renderSession(record, live) {
    const state = (record && record.state) || {};
    renderMap(record);
    const micKey = Object.prototype.hasOwnProperty.call(MIC_LABELS, live.mic) ? live.mic : "offline";
    const micNode = el("obsMic");
    micNode.textContent = MIC_LABELS[micKey];
    micNode.className = "corner corner-right" + (micKey === "ai_speaking" ? " mic-ai" : "");
    const caption = String(live.partial || live.last_user || "");
    el("obsCaption").textContent = caption;
    const reply = String(live.last_reply || "");
    el("obsReply").textContent = reply;
    const action = String(live.last_action || "");
    const reason = String(live.last_reason || "");
    let decision = "";
    if (action === "listen") { decision = "听着，没打断"; }
    else if (action) { decision = (ACTION_LABELS[action] || action) + (reason ? " · " + reason : ""); }
    el("obsDecision").textContent = reply ? decision : (action === "listen" ? "听着，没打断" : decision);
    armSubtitleFade(caption + "|" + reply + "|" + decision);
    renderParking(state.parking_lot || []);
    const stats = record.stats || {};
    el("obsCounters").textContent = "说了 " + String(stats.user_turns || 0) + " 句 · 开口 " + String(stats.ai_spoke || 0) + " 次 · 拉回 " + String(stats.pull_backs || 0) + " 次";
  }
  function stopPolling() { window.clearInterval(timer); timer = 0; }
  async function fetchJson(url) {
    const response = await fetch(url);
    const data = await response.json();
    if (!response.ok) {
      const message = (data && data.error && data.error.message) || "加载失败。";
      throw new Error(String(message));
    }
    return data;
  }
  async function pollOnce() {
    if (!sessionId) { return; }
    let record = null;
    try { record = await fetchJson("/api/sessions/" + sessionId); }
    catch (e) { showMessage("还没有指定要看的星图。从开始页勾选“录视频：同时打开星图窗口”再开始。"); stopPolling(); return; }
    let live = {};
    try { live = await fetchJson("/api/sessions/" + sessionId + "/live"); } catch (e) {}
    renderSession(record, live || {});
    if (record.status === "finished") {
      const title = (record.result && record.result.title) || "成果";
      const banner = el("obsFinished");
      banner.textContent = "灯亮了 · " + String(title);
      banner.hidden = false;
      el("obsMic").textContent = "未连接";
      stopPolling();
    }
  }
  function init() {
    sessionId = sessionParam();
    if (!/^[0-9a-f]{32}$/.test(sessionId)) {
      showMessage("还没有指定要看的星图。从开始页勾选“录视频：同时打开星图窗口”再开始。");
      return;
    }
    pollOnce();
    timer = window.setInterval(pollOnce, 1000);
  }
  document.addEventListener("DOMContentLoaded", init);
  return { init: init, pollOnce: pollOnce };
})();
